namespace ghidra.app.util.recognizer;

public class YbsRecognizer : Recognizer {
    /* @Override */
	public string recognize(byte[] bytes) {
        if (bytes.length >= numberOfBytesRequired()) {
            if (bytes[0] == (byte) 0x59 &&
                bytes[1] == (byte) 0x42 &&
                bytes[2] == (byte) 0x53 &&
                bytes[3] == (byte) 0x01  ) {
                return "File appears to be a YBS compressed file";
            }
        }
        return null;
    }

    /* @Override */
	public int getPriority() {
        return 100;
    }

    /* @Override */
	public int numberOfBytesRequired() {
        return 4;
    }
}
